"""Intent tests for agents.TabularAgent (M1-T15): TC-12 (AGENT-01), TC-13 (AGENT-02), ABL-03."""

import json
from pathlib import Path
from typing import Any

import numpy as np
import pytest

from rllab.agents import TabularAgent
from rllab.core import AgentParams, Exploration, Transition

FIXTURES = Path(__file__).resolve().parents[2] / "fixtures" / "rllab"
CONTRACTS = Path(__file__).resolve().parents[2] / "contracts"
CORRIDOR_LENGTH = 10
N_ACTIONS = 2
SEED = 0


def _load(path: Path) -> Any:
    return json.loads(path.read_text())


@pytest.fixture
def tc12_input() -> Any:
    return _load(FIXTURES / "TC-12" / "input.json")


@pytest.fixture
def tc12_expected() -> Any:
    return _load(FIXTURES / "TC-12" / "expected.json")


@pytest.fixture
def tc13_input() -> Any:
    return _load(FIXTURES / "TC-13" / "input.json")


@pytest.fixture
def tc13_expected() -> Any:
    return _load(FIXTURES / "TC-13" / "expected.json")


def _tabular_params() -> AgentParams:
    sample = _load(CONTRACTS / "core.AgentParams" / "samples.json")["tabular"]
    return AgentParams(**sample)


def _onehot(cell: int) -> np.ndarray:
    obs = np.zeros((1, CORRIDOR_LENGTH), dtype=np.float32)
    if cell < CORRIDOR_LENGTH:
        obs[0, cell] = 1.0
    return obs


def _transition(
    obs_cell: int,
    action: int,
    reward: float,
    next_cell: int,
    terminated: bool,
    *,
    truncated: bool = False,
) -> Transition:
    return Transition(
        obs=_onehot(obs_cell),
        actions=np.array([action], dtype=np.int64),
        reward=np.array([reward], dtype=np.float32),
        next_obs=_onehot(next_cell),
        terminated=np.array([terminated], dtype=bool),
        active=np.array([True], dtype=bool),
        truncated=truncated,
    )


def _from_fixture(spec: Any, **kwargs: Any) -> Transition:
    return _transition(
        spec["obs_cell"],
        spec["action"],
        spec["reward"],
        spec["next_cell"],
        spec["terminated"],
        **kwargs,
    )


def _agent(
    params: AgentParams | None = None,
    exploration: Exploration | None = None,
    *,
    explore_enabled: bool = True,
) -> TabularAgent:
    return TabularAgent(
        N_ACTIONS,
        params if params is not None else _tabular_params(),
        exploration if exploration is not None else Exploration(),
        seed=SEED,
        explore_enabled=explore_enabled,
    )


def _tc12_agent(tc12_input: Any) -> TabularAgent:
    params = AgentParams(lr=tc12_input["lr"], gamma=tc12_input["gamma"])
    return _agent(params)


@pytest.mark.intent
def test_tc12_terminal_update_then_bootstrapped_update(tc12_input, tc12_expected):
    tol = tc12_expected["tol"]
    agent = _tc12_agent(tc12_input)
    first, second = tc12_input["transitions"]

    agent.learn(_from_fixture(first))
    after_1 = tc12_expected["after_1"]
    values_1 = agent.values(_onehot(after_1["cell"]))
    assert values_1[after_1["action"]] == pytest.approx(after_1["value"], abs=tol)

    agent.learn(_from_fixture(second))
    after_2 = tc12_expected["after_2"]
    values_2 = agent.values(_onehot(after_2["cell"]))
    assert values_2[after_2["action"]] == pytest.approx(after_2["value"], abs=tol)
    # The earlier entry is untouched by the second update.
    again = agent.values(_onehot(after_1["cell"]))
    assert again[after_1["action"]] == pytest.approx(after_1["value"], abs=tol)


@pytest.mark.intent
def test_tc12_truncated_step_still_bootstraps(tc12_input, tc12_expected):
    tol = tc12_expected["tol"]
    agent = _tc12_agent(tc12_input)
    first, second = tc12_input["transitions"]
    agent.learn(_from_fixture(first))
    agent.learn(_from_fixture(second, truncated=True))
    after_2 = tc12_expected["after_2"]
    values = agent.values(_onehot(after_2["cell"]))
    assert values[after_2["action"]] == pytest.approx(after_2["value"], abs=tol)


@pytest.mark.intent
def test_terminated_step_does_not_bootstrap_from_next_value(tc12_input, tc12_expected):
    tol = tc12_expected["tol"]
    agent = _tc12_agent(tc12_input)
    first, second = tc12_input["transitions"]
    agent.learn(_from_fixture(first))
    # Same as the second step, but the agent's real end: next value must be ignored.
    terminal = dict(second, terminated=True)
    agent.learn(_from_fixture(terminal))
    values = agent.values(_onehot(second["obs_cell"]))
    assert values[second["action"]] == pytest.approx(0.0, abs=tol)
    assert agent.values(_onehot(first["obs_cell"]))[first["action"]] > 0.0


@pytest.mark.intent
def test_values_start_at_zero_with_float64_row_per_action():
    agent = _agent()
    values = agent.values(_onehot(3))
    assert values.shape == (N_ACTIONS,)
    assert values.dtype == np.float64
    assert np.array_equal(values, np.zeros(N_ACTIONS))


@pytest.mark.intent
def test_values_does_not_change_the_table(tc12_input):
    agent = _tc12_agent(tc12_input)
    first = tc12_input["transitions"][0]
    agent.learn(_from_fixture(first))
    unseen = _onehot(2)
    assert np.array_equal(agent.values(unseen), np.zeros(N_ACTIONS))
    before = agent.values(_onehot(first["obs_cell"])).copy()
    for _ in range(3):
        agent.values(unseen)
        after = agent.values(_onehot(first["obs_cell"]))
    assert np.array_equal(before, after)
    assert np.array_equal(agent.values(unseen), np.zeros(N_ACTIONS))


@pytest.mark.intent
def test_values_rejects_a_batch_other_than_one():
