def test_abl03_no_explore_always_takes_the_argmax():
    agent = _trained_two_state_agent(explore_enabled=False, exploration=Exploration())
    # Exploration is near its start rate, so an exploring agent would act randomly often.
    assert agent.epsilon(2) > 0.9
    cells = (8, 3)
    greedy = {cell: int(np.argmax(agent.values(_onehot(cell)))) for cell in cells}
    assert greedy == {8: 1, 3: 0}
    mismatches = 0
    for i in range(1000):
        cell = cells[i % 2]
        action = agent.act(_onehot(cell), explore=True)
        assert action.shape == (1,)
        if int(action[0]) != greedy[cell]:
            mismatches += 1
    assert mismatches == 0


@pytest.mark.intent
def test_exploring_agent_does_take_non_greedy_actions():
    agent = _trained_two_state_agent(explore_enabled=True, exploration=Exploration())
    greedy = int(np.argmax(agent.values(_onehot(8))))
    actions = [int(agent.act(_onehot(8), explore=True)[0]) for _ in range(1000)]
    assert any(a != greedy for a in actions)
    assert set(actions) <= set(range(N_ACTIONS))


@pytest.mark.intent
def test_explore_false_takes_the_best_valued_action():
    agent = _trained_two_state_agent(explore_enabled=True, exploration=Exploration())
    for cell, best in ((8, 1), (3, 0)):
        for _ in range(200):
            assert int(agent.act(_onehot(cell), explore=False)[0]) == best


@pytest.mark.intent
def test_act_explore_uses_epsilon_of_learn_calls_so_far():
    # Rate reaches 0 after two learn calls, so exploring acts are then greedy.
    exploration = Exploration(start=1.0, end=0.0, decay_steps=2)
    agent = _trained_two_state_agent(explore_enabled=True, exploration=exploration)
    assert agent.epsilon(2) == pytest.approx(0.0, abs=1e-12)
    for _ in range(500):
        assert int(agent.act(_onehot(8), explore=True)[0]) == 1
        assert int(agent.act(_onehot(3), explore=True)[0]) == 0


@pytest.mark.intent
def test_save_then_load_restores_values_and_actions(tmp_path):
    agent = _trained_two_state_agent(explore_enabled=True, exploration=Exploration())
    path = tmp_path / "tabular.npz"
    agent.save(path)
    fresh = _agent()
    fresh.load(path)
    for cell in (8, 3, 5):
        obs = _onehot(cell)
        assert np.array_equal(fresh.values(obs), agent.values(obs))
        assert np.array_equal(fresh.act(obs, explore=False), agent.act(obs, explore=False))
    with np.load(path) as archive:
        assert len(archive.files) > 0
